    rows=[('causal_treatment','JMP Pro binary/continuous treatment and outcome;ATE/ATET and mean potential outcomes','Target population,consistency,exchangeability,support and correct nuisance-model scope'),('uplift','Interaction-based partition and documented multiplicity/validation controls','Full selection/evaluation law,dependent units,treatment pooling and costs'),('continuous_dose','Normal conditional density,stabilized MSM and GPS prose','Observed support versus model extrapolation;inspect image equations before exact vendor formula claims'),('supplied_iv','Model-implied instruments and equation diagnostics','Instrument validity and supplied-model restrictions,not unrestricted discovery'),('survival','Independent-cause survival display and omit-cause scenario','Event/censoring/risk sets and explicit causal removal mechanism'),('panels_longitudinal_discovery','Selected evidence does not establish exhaustive contracts','Acquire missing exact-edition primary scopes;do not infer product-wide absence'),('agents_cli_mcp','Proposed analyst or entitled isolated workflow','Exact official automation profile,artifact,rights,typed refusal and recovery')]
