    write(BASE/'omissions-register.json',dict(next_action=next_action,global_blocker=False,known_routes=['Exact official edition/API/rights acquisition','Fresh permitted equation-image inspection','Finite target,coding,selection,support and event fixtures','Analyst/worker round trips and complete costs'],remaining=['Uninspected image-only formulas','Current artifact and older/newer edition parity','Exact service/API entitlement and prices','Native public tests and broad panel/longitudinal/discovery coverage'],unknown_without_information=['Unobserved bank confounding','Off-support dose responses','Causal mechanisms for removing competing events','Universal adaptive/dependent-data uncertainty']))
    choice=dict(candidate='JMP',canonical_candidate='JMP Pro causal treatment and separately scoped uplift,SEM and survival workflows',decision='reference',selected_revision='Retained official bytes;no binary selected',selected_version='Distinct19.2/19.0/19/18.1/16documentation profiles',reason='Documented workflows require target,selection,support,event and edition-specific contracts.',alternatives=[dict(route='adopt',decision='defer',reason='No universal causal,selection,artifact or entitlement qualification'),dict(route='integrate',decision='conditional',reason='Entitled supported analyst or isolated worker workflow with public fixtures'),dict(route='port',decision='unavailable_without_separate_authorization',reason='No proprietary implementation reuse authorization;public methods are a separate project'),dict(route='reference',decision='retain',reason='Authentic official prose and independent finite witnesses'),dict(route='reject',decision='restricted',reason='Reject unsupported pooled-treatment,off-support,selection and removal claims')],owners=[dict(role=r,responsibility=v) for r,v in [('Scientific','Target,intervention,assumptions and loss'),('Statistical','Selection,dependence,support and event law'),('Adapter','Treatment order,weights,events,typed outputs and recovery'),('Platform/procurement','Supported automation,artifact,rights and costs')]],costs=dict(prices='Unmeasured;21000USD authored example',categories=['entitlement','artifact','conversion','all calls','failures','review','maintenance']),maintenance='Exact supported artifact and quote unresolved',revisit_trigger=next_action,integration_allowed=False,capabilities=[],limitations=LIMITS)
